INSERT INTO `att_audit_rule` VALUES (9,'字段字符类型校验','1','5','1','检查字段值是否为期望的字符组成（字母、数字等）','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'107','检查字段值是否为期望的字符组成（字母、数字等）','• 手机号字段应为纯数字，出现“+86-138****”或“138x123”触发告警\n• 物流单号字段要求仅含字母+数字，禁止中文或特殊符号\n• 身份证字段只允许18位数字或带X的合法身份证号',NULL,'CHARACTER_VALIDATION');
INSERT INTO `att_audit_rule` VALUES (10,'字段长度范围校验','1','5','1','检查字段长度是否在定义范围内（如11位手机号）','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'108','检查字段长度是否在定义范围内（如11位手机号）','• 手机号字段必须为11位，过长/过短为非法\\n• 银行卡号字段不得超过19位\\n• 姓名字段超过50字符为异常（如自动抓取异常数据）',NULL,'LENGTH_VALIDATION');
INSERT INTO `att_audit_rule` VALUES (11,'日期时间格式校验','1','5','1','检查字段是否为合法的时间格式（如yyyy-MM-dd）','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'109','检查字段是否为合法的时间格式（如yyyy-MM-dd）','• 日期字段要求格式为yyyy-MM-dd，禁止yyyy/MM/dd或中文日期格式\\n• 日期时间字段必须为yyyy-MM-dd HH:mm:ss，缺失秒或用12小时制视为非法\\n• 禁止出现“0000-00-00”或“1970-01-01”作为默认占位',NULL,NULL);
INSERT INTO `att_audit_rule` VALUES (12,'数值字段精度校验','1','5','1','检查小数位数是否符合业务定义（如保留2位）','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'110','检查小数位数是否符合业务定义（如保留2位）','• 金额字段小数点后最多保留2位，保留3位或更多为异常\\n• 利率字段精度需为4位，如0.0523，不能为0.052312',NULL,'DECIMAL_PRECISION_VALIDATION');
INSERT INTO `att_audit_rule` VALUES (13,'枚举值校验','1','5','1','检查字段值是否在字典或枚举集中','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'111','检查字段值是否在字典或枚举集中','• 性别字段仅允许“男/女/未知”，出现“female”、“1”视为非法\\n• 订单状态字段必须在“已下单/已付款/已发货/已取消”内',NULL,'ENUM_VALIDATION');
INSERT INTO `att_audit_rule` VALUES (14,'主数据引用一致性校验','1','5','1','检查引用字段是否在主数据中存在','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'112','检查引用字段是否在主数据中存在','• 客户ID字段在客户主数据中找不到对应记录则视为无效\\n• 门店编码未能在门店主数据中匹配成功时标记为脏数据',NULL,NULL);
INSERT INTO `att_audit_rule` VALUES (15,'逻辑模型一致性校验','1','5','1','检查表结构是否与数据模型一致','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'113','检查表结构是否与数据模型一致','• 数据集字段数量多于模型定义（如多出“备用字段1~3”）则为冗余字段\\n• 数据类型与模型不符，如应为decimal结果为varchar',NULL,NULL);
INSERT INTO `att_audit_rule` VALUES (16,'字段元信息完整性校验','1','5','1','检查字段是否配置必要的元信息（类型、说明等）','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'114','检查字段是否配置必要的元信息（类型、说明等）','• 字段未配置中文名称或业务定义，不利于后续治理与血缘追踪\\n• 缺失字段类型定义，影响自动校验与建模',NULL,NULL);
INSERT INTO `att_audit_rule` VALUES (17,'时间字段顺序逻辑校验','1','5','1','检查多个时间字段之间的前后逻辑','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'115','检查多个时间字段之间的前后逻辑','• 订单完成时间早于创建时间为异常\\n• 上岗时间应早于离职时间',NULL,'TIME_ORDER_VALIDATION');
INSERT INTO `att_audit_rule` VALUES (18,'数值字段逻辑关系校验','1','5','1','检查多个数值字段之间的业务逻辑关系','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'116','检查多个数值字段之间的业务逻辑关系','• 实际付款金额不得超过应付款，否则为溢付错误\\n• 销售数量不得超过库存数量',NULL,NULL);
INSERT INTO `att_audit_rule` VALUES (19,'状态字段依赖项校验','1','5','1','检查某状态下是否填写了必须字段','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'117','检查某状态下是否填写了必须字段','• 状态=已取消时，取消原因字段不能为空\\n• 状态=完成时，必须填写完成时间、操作人',NULL,NULL);
INSERT INTO `att_audit_rule` VALUES (20,'互斥字段冲突校验','1','5','1','检查不能同时存在的字段值是否冲突','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'118','检查不能同时存在的字段值是否冲突','• 内部客户标志与外部客户标志只能选其一\\n• 线上订单标识与线下订单标识不能同时为“是”',NULL,NULL);
INSERT INTO `att_audit_rule` VALUES (21,'敏感字段脱敏校验','1','5','1','检查敏感字段是否存在明文泄露风险','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'119','检查敏感字段是否存在明文泄露风险','• 客户手机号展示为“138****1234”\\n• 身份证号仅展示前6位和最后4位，中间脱敏\\n• 银行卡号仅展示后四位，其余使用“*”替代',NULL,NULL);
INSERT INTO `att_audit_rule` VALUES (22,'必填字段非空校验','2','5','1','检查强制必填字段是否存在空值','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'203','检查强制必填字段是否存在空值','• 用户ID、订单号、收件地址等字段不能为空\\n• 财务系统中凭证编号为强制必填项',NULL,NULL);
INSERT INTO `att_audit_rule` VALUES (23,'非法占位值识别','2','5','1','检查是否使用非法占位（如N/A、-999）替代有效值','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'204','检查是否使用非法占位（如N/A、-999）替代有效值','• 年龄字段为-1、“N/A”、NULL等值视为缺失\\n• 数量字段为“-999”、“未知”表示错误占位值，需清洗',NULL,NULL);
INSERT INTO `att_audit_rule` VALUES (24,'字段组完整性校验','2','5','1','检查逻辑上应成对出现的字段是否齐全','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'205','检查逻辑上应成对出现的字段是否齐全','• 经纬度缺一不可，否则无法定位\\n• 邮箱和邮箱类型需同时填写，缺任一视为不完整',NULL,'GROUP_FIELD_COMPLETENESS');
INSERT INTO `att_audit_rule` VALUES (25,'整记录缺失检查校验','2','5','1','检查是否存在除主键外字段全为空的记录','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'206','检查是否存在除主键外字段全为空的记录','• 某条记录仅有主键，其他字段全为空，应标记为垃圾数据\\n• 批量导入后出现内容空壳行（仅有ID），视为无效',NULL,NULL);
INSERT INTO `att_audit_rule` VALUES (26,'条件字段完整性校验','2','5','1','检查满足某条件时，相关字段是否已填写','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'207','检查满足某条件时，相关字段是否已填写','• 是否加班=是，则加班工时不能为空\\n• 是否出差=是，则必须填写出差地点',NULL,NULL);
INSERT INTO `att_audit_rule` VALUES (27,'数值字段范围校验','3','5','1','检查字段值是否落在业务定义的合理区间','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'306','检查字段值是否落在业务定义的合理区间','• 年龄字段不得小于0或大于120\\n• 折扣字段不得超过100%，小于0也不合法',NULL,'NUMERIC_RANGE_VALIDATION');
INSERT INTO `att_audit_rule` VALUES (28,'数值字段逻辑值合法校验','3','5','1','校验字段值是否违反业务规则（如库存不为负，销售额不能小于0）','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'307','校验字段值是否违反业务规则（如库存不为负，销售额不能小于0）','• 销售额出现负值为异常，需判断是否退款未记录\\n• 库存为负说明有异常出库操作',NULL,NULL);
INSERT INTO `att_audit_rule` VALUES (29,'数值字段异常值识别','3','5','1','检测异常的极端数值或明显错误数据','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'308','检测异常的极端数值或明显错误数据','• 薪资字段为“99999999”视为默认或错误写入\\n• 年龄=200、商品价格=0.01等为极端可疑值',NULL,NULL);
INSERT INTO `att_audit_rule` VALUES (30,'脏数据识别','3','5','1','标记无意义、无效或错误占位的数据值','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'309','标记无意义、无效或错误占位的数据值','• 性别字段为“unknown”、错误拼写如“Unkown”应纠正或剔除\\n• 组织名称字段为“test”、“123”等为无效数据',NULL,NULL);
INSERT INTO `att_audit_rule` VALUES (31,'单字段唯一性校验','3','5','1','检查字段值是否唯一（如订单号）','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'310','检查字段值是否唯一（如订单号）','• 订单号重复会导致资金、库存重复记录\\n• 员工编号重复会干扰排班与考勤',NULL,NULL);
INSERT INTO `att_audit_rule` VALUES (32,'多字段组合唯一性校验','3','5','1','检查字段组合在全表中是否唯一','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'311','检查字段组合在全表中是否唯一','• 同一用户在某一天只能有一条签到记录\\n• [门店+SKU+日期] 不得重复出现',NULL,'COMPOSITE_UNIQUENESS_VALIDATION');
INSERT INTO `att_audit_rule` VALUES (33,'跨表字段值一致性校验','4','5','1','检查同一字段在不同表间是否值一致','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'403','检查同一字段在不同表间是否值一致','• 用户表中姓名与订单表中收件人姓名需一致\\n• 员工信息在HR表与考勤表中性别字段不能冲突',NULL,NULL);
INSERT INTO `att_audit_rule` VALUES (34,'外键有效性校验','4','5','1','检查外键值是否存在于目标主表中','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'404','检查外键值是否存在于目标主表中','• 订单表中商品ID必须能在商品主表中找到\\n• 工单记录引用的操作人ID必须在员工表中存在',NULL,NULL);
INSERT INTO `att_audit_rule` VALUES (35,'状态字段一致性校验','4','5','1','检查状态与其他字段值是否存在逻辑冲突','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'405','检查状态与其他字段值是否存在逻辑冲突','• 状态=未审核但存在审核时间，说明数据录入异常\\n• 状态=草稿但存在付款金额不应出现',NULL,NULL);
INSERT INTO `att_audit_rule` VALUES (36,'时间字段先后顺序校验','5','5','1','检查时间字段是否有逻辑上的早晚关系','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'504','流程控制、事件日志、审批流程等\n','• 项目开始时间不能晚于结束时间\n• 发货时间不能早于下单时间',NULL,NULL);
INSERT INTO `att_clean_rule` VALUES (1,'数值边界调整','1','将超出预设范围的数值调整为范围的边界值。','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'年龄 > 150 → 设置为 150','3','将超出预设范围的数值调整为范围的边界值。','WITHIN_BOUNDARY','001','A01A01');
INSERT INTO `att_clean_rule` VALUES (2,'字段值替换','1','将不符合预设规则的数据值替换为指定的默认值或空值','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'状态字段值为“abc” → 替换为“未知”','3','将不符合预设规则的数据值替换为指定的默认值或空值','VALUE_REPLACE','002','A01A01');
INSERT INTO `att_clean_rule` VALUES (3,'字符串转数值','1','将纯数字字符串转换为数值类型','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'“1000” → 1000','4','将纯数字字符串转换为数值类型',NULL,'003','A01A02');
INSERT INTO `att_clean_rule` VALUES (4,'字符串转日期','1','将符合格式的字符串转换为日期类型','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'“2025-07-01” → 日期类型','4','将符合格式的字符串转换为日期类型',NULL,'004','A01A02');
INSERT INTO `att_clean_rule` VALUES (5,'任意类型转布尔值','1','将“是/否”、“1/0”、“true/false”等转换为布尔值','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'“是” → true','4','将“是/否”、“1/0”、“true/false”等转换为布尔值',NULL,'005','A01A02');
INSERT INTO `att_clean_rule` VALUES (6,'手机号格式统一','1','统一手机号为国内11位纯数字格式，去除国家码、空格、短横线等','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'“+86-138 1234 5678” → “13812345678”','5','统一手机号为国内11位纯数字格式，去除国家码、空格、短横线等','PHONE_FORMAT_STD','006','A01A03');
INSERT INTO `att_clean_rule` VALUES (7,'日期格式统一','1','统一各种日期格式为指定标准格式（如 yyyy-MM-dd），支持配置模板','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'“20250701” → “2025-07-01”','5','统一各种日期格式为指定标准格式（如 yyyy-MM-dd），支持配置模板','DATE_FORMAT_STD','007','A01A03');
INSERT INTO `att_clean_rule` VALUES (8,'小数位统一','1','将数值字段统一保留指定的小数位数（如保留两位小数）','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'“12.3” → “12.30”；“100” → “100.00”','5','将数值字段统一保留指定的小数位数（如保留两位小数）','FIX_TO_PRECISION','008','A01A03');
INSERT INTO `att_clean_rule` VALUES (9,'去除字段空格','1','去除字段中的前后空格或中间多余空格，提升匹配准确性','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'“  山西 省  ” → “山西省”，收尾、中间等','5','去除字段中的前后空格或中间多余空格，提升匹配准确性','REMOVE_WHITESPACE','009','A01A03');
INSERT INTO `att_clean_rule` VALUES (10,'字段前缀/后缀统一','1','对字段值统一加前缀或后缀，或去除非业务所需的标记','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'“编号123” → 去除“编号” → “123”','5','对字段值统一加前缀或后缀，或去除非业务所需的标记','ADD_PREFIX_SUFFIX','010','A01A03');
INSERT INTO `att_clean_rule` VALUES (11,'正则表达式替换','1','通过正则表达式匹配符合特定规则的文本，并将其批量替换为指定内容','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'使用 (\\d{4})/(\\d{2})/(\\d{2}) 匹配 2026/08/18，替换为 $1-$2-$3 后得到 2026-08-18','5','批量统一文本中的日期格式，提高数据处理效率','SIMPLE_REPLACE','011','A01A03');
INSERT INTO `att_clean_rule` VALUES (12,'超长字段截断','1','当字段长度超过指定长度时进行截断处理','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'描述字段超100字符 → 截取前100字符','6','当字段长度超过指定长度时进行截断处理','STRING_SUBSTR','012','A01A04');
INSERT INTO `att_clean_rule` VALUES (13,'字段补零','1','在字段前/后补0，保持固定长度','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'组织编码“1” → 补全为“00001”','6','在字段前/后补0，保持固定长度',NULL,'013','A01A04');
INSERT INTO `att_clean_rule` VALUES (14,'数值空值填充','1','将空的数值字段填充为指定默认值（如 0、-1、平均数等）','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'年龄字段为空 → 配置默认值为 0','21','将空的数值字段填充为指定默认值（如 0、-1、平均数等）',NULL,'014','A02A01');
INSERT INTO `att_clean_rule` VALUES (15,'字符串空值填充','1','将空的字符串字段填充为指定字符（如“未知”、“无”）','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'籍贯字段为空 → 配置默认值为“未知”','21','将空的字符串字段填充为指定字符（如“未知”、“无”）',NULL,'015','A02A01');
INSERT INTO `att_clean_rule` VALUES (16,'布尔空值填充','1','布尔字段为空时填充为指定布尔值（如 false / true）','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'是否启用字段为空 → 配置默认值为 false','21','布尔字段为空时填充为指定布尔值（如 false / true）',NULL,'016','A02A01');
INSERT INTO `att_clean_rule` VALUES (17,'日期空值填充','1','日期字段为空时填充为配置的默认日期（如当前日期、昨天、固定值等）','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'注册时间为空 → 配置默认值为“当前日期”','21','日期字段为空时填充为配置的默认日期（如当前日期、昨天、固定值等）','DATE_FILL_NULL','017','A02A01');
INSERT INTO `att_clean_rule` VALUES (18,'全字段为空删除','1','整行所有字段都为空、null 或空字符串时，直接删除该记录','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'{姓名: null, 手机: \"\", 地址: null} → 删除','22','整行所有字段都为空、null 或空字符串时，直接删除该记录',NULL,'018','A02A02');
INSERT INTO `att_clean_rule` VALUES (19,'组合字段为空删除','1','配置关键字段（如主键）为空时，删除整行记录','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'用户ID为 null → 删除该记录','22','配置关键字段（如主键）为空时，删除整行记录','REMOVE_EMPTY_COMBINATION','019','A02A02');
INSERT INTO `att_clean_rule` VALUES (20,'单位标准化类','1','将字段中的值根据配置的换算关系，从源单位换算为目标单位，保留数值精度','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'“2.5 万元” → “25000 元”；“3 kg” → “3000 g”','30','将字段中的值根据配置的换算关系，从源单位换算为目标单位，保留数值精度',NULL,'020','A03A01');
INSERT INTO `att_clean_rule` VALUES (21,'字段值转大写','1','将字段值统一转为全大写，适用于省份、代码、简称等字段','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'“shanxi” → “SHANXI”','31','将字段值统一转为全大写，适用于省份、代码、简称等字段','TO_UPPERCASE','021','A03A02');
INSERT INTO `att_clean_rule` VALUES (22,'字段值转小写','1','将字段值统一转为全小写，适用于邮箱、域名等字段','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'“EXAMPLE@MAIL.COM” → “example@mail.com”','31','将字段值统一转为全小写，适用于邮箱、域名等字段','TO_LOWERCASE','022','A03A02');
INSERT INTO `att_clean_rule` VALUES (23,'字段值首字母大写','1','将字段中的每个单词首字母大写，其余转为小写','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'“beijing city” → “Beijing City”','31','将字段中的每个单词首字母大写，其余转为小写',NULL,'023','A03A02');
INSERT INTO `att_clean_rule` VALUES (24,'枚举值映射标准化','1','将字段值根据配置字典进行映射替换，确保值域统一','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'“1” → “启用”；“0” → “停用”','32','将字段值根据配置字典进行映射替换，确保值域统一','MENU_CUSTOM','024','A03A03');
INSERT INTO `att_clean_rule` VALUES (25,'按主键去重（保留首条）','1','按指定唯一标识字段对记录去重，仅保留首条出现的数据，适用于无时间戳场景','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'按“客户ID”去重，保留最先出现的记录','39','按指定唯一标识字段对记录去重，仅保留首条出现的数据，适用于无时间戳场景','PK_DEDUP_FIRST','025','A04A01');
INSERT INTO `att_clean_rule` VALUES (26,'按主键去重（按时间字段保留最新）','1','配置时间字段，在重复记录中仅保留时间最新的一条','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'按“订单编号”去重，保留“更新时间”最大的一条记录','39','配置时间字段，在重复记录中仅保留时间最新的一条',NULL,'026','A04A01');
INSERT INTO `att_clean_rule` VALUES (27,'按优先级字段保留记录','1','当记录存在多个来源或等级标记时，按照优先级高的记录进行保留','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'“数据来源”为“系统录入”优先于“Excel导入”，如果多条都是“系统录入”则应用最新一条','39','当记录存在多个来源或等级标记时，按照优先级高的记录进行保留',NULL,'027','A04A01');
INSERT INTO `att_clean_rule` VALUES (28,'按非空字段优先保留记录','1','当关键字段存在空值时，优先保留值完整的记录','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'两条重复记录中一条手机号为空 → 保留手机号不为空的那条','39','当关键字段存在空值时，优先保留值完整的记录',NULL,'028','A04A01');
INSERT INTO `att_clean_rule` VALUES (29,'按组合字段去重（保留最新或首条）','1','指定多个字段作为联合唯一键，对重复记录进行去重，可配置保留策略（首条、最新）','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'按“用户ID + 年份”去重，保留“更新时间”最大的一条记录','39','指定多个字段作为联合唯一键，对重复记录进行去重，可配置保留策略（首条、最新）','KEEP_LATEST_OR_FIRST','029','A04A01');
INSERT INTO `att_clean_rule` VALUES (30,'替换无效数值','1','将不在合法范围内的数值字段替换为指定默认值（如负数、过大值、异常标识值）','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'年龄字段为 -1 或 999 → 替换为 null 或 0','46','将不在合法范围内的数值字段替换为指定默认值（如负数、过大值、异常标识值）',NULL,'030','A05A01');
INSERT INTO `att_clean_rule` VALUES (31,'替换非法枚举值','1','当字段值不在指定值域集合中时，替换为默认值或空值','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'状态字段值为“异常值99” → 替换为“未知”','46','当字段值不在指定值域集合中时，替换为默认值或空值',NULL,'031','A05A01');
INSERT INTO `att_clean_rule` VALUES (32,'替换无效时间格式','1','当字段值不符合日期时间标准格式时，替换为默认时间或空值','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'“32/13/2023” → 替换为 null 或“1970-01-01”','46','当字段值不符合日期时间标准格式时，替换为默认时间或空值',NULL,'032','A05A01');
INSERT INTO `att_clean_rule` VALUES (33,'替换非法布尔值','1','将字段中不符合布尔定义的值替换为默认布尔值','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'“abc” → 替换为 false','46','将字段中不符合布尔定义的值替换为默认布尔值',NULL,'033','A05A01');
INSERT INTO `att_clean_rule` VALUES (34,'关键词脱敏','1','将字段值中包含的敏感词进行掩码处理，支持配置脱敏字符','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'“这是一条涉黄内容” → “这是一条***内容”','47','将字段值中包含的敏感词进行掩码处理，支持配置脱敏字符',NULL,'034','A05A02');
INSERT INTO `att_clean_rule` VALUES (35,'敏感词替换','1','将命中词表中的敏感词替换为指定文本（如“未知”、“违规内容”）','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'“暴恐言论” → 替换为“违规内容”','47','将命中词表中的敏感词替换为指定文本（如“未知”、“违规内容”）',NULL,'035','A05A02');
INSERT INTO `att_clean_rule` VALUES (36,'修正未来时间值','1','当时间字段值晚于当前时间时，自动修正为当前时间或指定边界值','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'注册时间为“2099-12-31” → 替换为“当前系统时间”','55','当时间字段值晚于当前时间时，自动修正为当前时间或指定边界值',NULL,'036','A06A01');
INSERT INTO `att_clean_rule` VALUES (37,'校正超前时间差值','1','当字段时间超过当前时间指定间隔（如7天）时，进行修正处理','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'预约时间为当前时间+15天 → 替换为“当前时间+7天”','55','当字段时间超过当前时间指定间隔（如7天）时，进行修正处理',NULL,'037','A06A01');
INSERT INTO `att_clean_rule` VALUES (38,'填补空时间为当前时间','1','当时间字段为空时，填充为系统当前时间或默认时间','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'更新时间字段为 null → 替换为“2025-07-18 10:00:00”','56','当时间字段为空时，填充为系统当前时间或默认时间',NULL,'038','A06A02');
INSERT INTO `att_clean_rule` VALUES (39,'清理过期记录','1','当记录中的时间字段早于当前时间指定阈值时（如30天），标记或删除','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'最后登录时间早于30天前 → 该用户记录设为“过期”','57','当记录中的时间字段早于当前时间指定阈值时（如30天），标记或删除','CHECK_EXPIRATION','039','A06A03');
INSERT INTO `att_clean_rule` VALUES (40,'修正历史时间边界','1','当字段值早于系统可接受最早时间时，替换为指定边界值','0','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL,'创建时间为“1900-01-01” → 替换为“2000-01-01”','57','当字段值早于系统可接受最早时间时，替换为指定边界值',NULL,'040','A06A03');
INSERT INTO `da_sensitive_level` VALUES (1,'1级（绝密）','1',NULL,NULL,'****','1','包含国家涉密信息、重大水利工程调度方案、涉安全生产的核心数据，一旦泄露将严重危害国家安全和重大工程运行安全。','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL);
INSERT INTO `da_sensitive_level` VALUES (2,'2级（机密）','1',NULL,NULL,'####','1','涉及水资源调度、水库运行、水源地保护、重要断面水质等关键业务数据，一旦泄露将影响行业管理和区域安全。','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL);
INSERT INTO `da_sensitive_level` VALUES (3,'3级（秘密）','2',2,10,'****','1','涉及日常监测数据（如流量、水位、雨量等明细）、取水户用水记录、内部分析报表等，一旦泄露会对业务管理和内部运行造成不利影响。保留前3位，其余用***替代（如“孙燕姿”→“孙***”）','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL);
INSERT INTO `da_sensitive_level` VALUES (4,'4级（内部）','2',3,8,'****','1','一般内部使用数据，如运维日志、调度流程记录、一般统计数据等，泄露影响较小但仍需内部保护。脱敏处理部分关键字段，如手机号138****5678','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL);
INSERT INTO `da_sensitive_level` VALUES (5,'5级（公开）','1',NULL,NULL,'****','1','可以对外公开的数据，如水雨情简报、已公开的监测站点水质年报、宣传类信息等，不涉及安全和隐私。可直接展示或仅弱化部分敏感字段（如展示省、市，不展示精确坐标）','1','0','bootstrap',1,CURRENT_TIMESTAMP,'bootstrap',1,CURRENT_TIMESTAMP,NULL);
